-- Kamizeta initial schema. Applied to Supabase project wenddiwiqissmponbtby.
create extension if not exists pgcrypto;
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,cover_image_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),name text not null,price_cents integer not null check(price_cents>=0),description text not null default '',product_code text not null unique,image_url text,reel_url text,category text not null,available_sizes text[] not null default array['PP','P','M','G','GG']::text[],is_published boolean not null default false,stock_status text not null default 'available' check(stock_status in('available','unavailable','preorder')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(cardinality(available_sizes)>0));
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,image_url text not null,drive_file_id text,alt_text text,position integer not null default 0,created_at timestamptz not null default now(),unique(product_id,image_url));
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',cpf text,phone text,instagram text,email text,address_line text,address_number text,address_complement text,neighborhood text,city text,state text,postal_code text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete restrict,buyer_name text not null,buyer_cpf text,address_snapshot jsonb not null default '{}'::jsonb,product_codes text[] not null default '{}'::text[],subtotal_cents integer not null check(subtotal_cents>=0),shipping_cents integer not null default 0 check(shipping_cents>=0),total_cents integer not null check(total_cents>=0),fulfillment_method text not null check(fulfillment_method in('delivery','pickup')),delivery_provider text,delivery_estimate_id text,delivery_estimate_expires_at timestamptz,delivery_estimate_payload jsonb,uber_delivery_code text,delivery_quote_status text not null default 'not_requested' check(delivery_quote_status in('not_requested','quoted','unavailable','expired','failed')),order_status text not null default 'awaiting_payment' check(order_status in('created','awaiting_payment','paid_pending_seller','in_progress','completed','cancelled','refunded')),payment_status text not null default 'pending' check(payment_status in('pending','paid','settled','cancelled','refunded','failed')),order_nsu text not null unique,email text not null,phone text,redirect_url text,infinitepay_checkout_url text,infinitepay_slug text,transaction_nsu text,capture_method text,receipt_url text,payment_payload jsonb,customer_notes text,cancelled_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(total_cents=subtotal_cents+shipping_cents));
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_code text not null,product_name text not null,image_url text,unit_price_cents integer not null check(unit_price_cents>=0),quantity integer not null check(quantity>0),size text not null,item_notes text,line_total_cents integer generated always as(unit_price_cents*quantity) stored,created_at timestamptz not null default now());
create table public.wishlist(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,product_id));
create table public.cart_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,size text not null,quantity integer not null default 1 check(quantity>0),item_notes text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,product_id,size,item_notes));
create table public.stories(id uuid primary key default gen_random_uuid(),title text not null default '',media_type text not null check(media_type in('image','youtube_short')),media_url text not null,category text,is_active boolean not null default false,published_at timestamptz,expires_at timestamptz,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.payment_events(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id) on delete set null,provider text not null default 'infinitepay',event_id text,event_type text not null,order_nsu text,transaction_nsu text,payload jsonb not null default '{}'::jsonb,processed_at timestamptz,processing_error text,received_at timestamptz not null default now(),unique(provider,event_id));
create table public.delivery_estimates(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,order_id uuid references public.orders(id) on delete set null,provider text not null default 'uber',estimate_id text not null,fee_cents integer not null check(fee_cents>=0),currency_code text not null default 'BRL',expires_at timestamptz,pickup_address jsonb not null default '{}'::jsonb,dropoff_address jsonb not null default '{}'::jsonb,provider_payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.store_settings(key text primary key,value jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null);
create index products_published_created_idx on public.products(is_published,created_at desc);
create index products_category_idx on public.products(category);
create index product_images_product_position_idx on public.product_images(product_id,position);
create index orders_user_created_idx on public.orders(user_id,created_at desc);
create index orders_status_created_idx on public.orders(order_status,created_at desc);
create index order_items_order_idx on public.order_items(order_id);
create index wishlist_user_idx on public.wishlist(user_id,created_at desc);
create index stories_active_expiry_idx on public.stories(is_active,published_at desc,expires_at);
create index payment_events_order_idx on public.payment_events(order_id,received_at desc);
create index delivery_estimates_order_idx on public.delivery_estimates(order_id,created_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now();return new;end;$$;
create or replace function public.sync_product_category() returns trigger language plpgsql security invoker set search_path='' as $$ begin insert into public.categories(name,cover_image_url) values(new.category,new.image_url) on conflict(name) do update set cover_image_url=coalesce(public.categories.cover_image_url,excluded.cover_image_url),updated_at=now();return new;end;$$;
create trigger products_sync_category after insert or update of category,image_url on public.products for each row execute function public.sync_product_category();
create or replace function public.handle_new_auth_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(user_id,full_name,email,phone,cpf) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.email,nullif(new.raw_user_meta_data->>'phone',''),nullif(new.raw_user_meta_data->>'cpf','')) on conflict(user_id) do update set email=excluded.email;return new;end;$$;
revoke all on function public.handle_new_auth_user() from public, anon, authenticated;
drop trigger if exists on_auth_user_created_kamizeta on auth.users;
create trigger on_auth_user_created_kamizeta after insert on auth.users for each row execute function public.handle_new_auth_user();
create or replace function public.is_store_admin() returns boolean language sql stable security invoker set search_path='' as $$ select coalesce((auth.jwt()->'app_metadata'->>'role')='admin',false);$$;
revoke all on function public.is_store_admin() from public;
grant execute on function public.is_store_admin() to authenticated;
create or replace function public.guard_order_update() returns trigger language plpgsql security invoker set search_path='' as $$ begin if not public.is_store_admin() then if new.user_id is distinct from old.user_id or new.payment_status is distinct from old.payment_status or new.order_status is distinct from old.order_status or new.total_cents is distinct from old.total_cents or new.subtotal_cents is distinct from old.subtotal_cents or new.shipping_cents is distinct from old.shipping_cents or new.order_nsu is distinct from old.order_nsu then raise exception 'Sensitive order fields can only be changed by server/admin';end if;end if;new.updated_at=now();return new;end;$$;
create trigger orders_guard_update before update on public.orders for each row execute function public.guard_order_update();
create or replace function public.refresh_category_cover() returns trigger language plpgsql security invoker set search_path='' as $$ begin update public.categories c set cover_image_url=(select p.image_url from public.products p where p.category=c.name and p.is_published=true order by p.created_at asc limit 1),updated_at=now() where c.name=coalesce(new.category,old.category);return coalesce(new,old);end;$$;
create trigger products_refresh_category_cover after update of is_published,image_url,category or delete on public.products for each row execute function public.refresh_category_cover();
alter table public.categories enable row level security;
alter table public.products enable row level security;
alter table public.product_images enable row level security;
alter table public.profiles enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.wishlist enable row level security;
alter table public.cart_items enable row level security;
alter table public.stories enable row level security;
alter table public.payment_events enable row level security;
alter table public.delivery_estimates enable row level security;
alter table public.store_settings enable row level security;
alter table public.admin_users enable row level security;
create policy "Public can read categories" on public.categories for select to anon,authenticated using(true);
create policy "Admins manage categories" on public.categories for all to authenticated using(public.is_store_admin()) with check(public.is_store_admin());
create policy "Public can read published products" on public.products for select to anon,authenticated using(is_published=true or public.is_store_admin());
create policy "Admins manage products" on public.products for all to authenticated using(public.is_store_admin()) with check(public.is_store_admin());
create policy "Public can read product images" on public.product_images for select to anon,authenticated using(exists(select 1 from public.products p where p.id=product_id and p.is_published=true) or public.is_store_admin());
create policy "Admins manage product images" on public.product_images for all to authenticated using(public.is_store_admin()) with check(public.is_store_admin());
create policy "Users read own profile" on public.profiles for select to authenticated using((select auth.uid())=user_id or public.is_store_admin());
create policy "Users create own profile" on public.profiles for insert to authenticated with check((select auth.uid())=user_id);
create policy "Users update own profile" on public.profiles for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "Users read own orders" on public.orders for select to authenticated using((select auth.uid())=user_id or public.is_store_admin());
create policy "Admins manage orders" on public.orders for all to authenticated using(public.is_store_admin()) with check(public.is_store_admin());
create policy "Users read own order items" on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=(select auth.uid())) or public.is_store_admin());
create policy "Admins manage order items" on public.order_items for all to authenticated using(public.is_store_admin()) with check(public.is_store_admin());
create policy "Users manage own wishlist" on public.wishlist for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "Users manage own cart" on public.cart_items for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "Public read active stories" on public.stories for select to anon,authenticated using((is_active=true and (published_at is null or published_at<=now()) and (expires_at is null or expires_at>now())) or public.is_store_admin());
create policy "Admins manage stories" on public.stories for all to authenticated using(public.is_store_admin()) with check(public.is_store_admin());
create policy "Admins read payment events" on public.payment_events for select to authenticated using(public.is_store_admin());
create policy "Admins read delivery estimates" on public.delivery_estimates for select to authenticated using(public.is_store_admin());
create policy "Public read public settings" on public.store_settings for select to anon,authenticated using(key in('public_order_count','public_store_info'));
create policy "Admins manage settings" on public.store_settings for all to authenticated using(public.is_store_admin()) with check(public.is_store_admin());
create policy "Admins read admins" on public.admin_users for select to authenticated using(public.is_store_admin());
grant select on public.categories,public.products,public.product_images,public.stories to anon,authenticated;
grant select,insert,update,delete on public.categories,public.products,public.product_images,public.stories to authenticated;
grant select,insert,update,delete on public.profiles,public.wishlist,public.cart_items to authenticated;
grant select on public.orders,public.order_items,public.store_settings to anon,authenticated;
grant select,insert,update,delete on public.orders,public.order_items,public.payment_events,public.delivery_estimates,public.store_settings,public.admin_users to authenticated;
